[CmdletBinding()]param([int]$BrokerPortBase=41020,[int]$OpencodePortBase=40970)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot '..\common\SpikeProofRuntime.psm1') -Force;$c=Get-SpikeProofConfig;Test-OllamaProofEndpoint|Out-Null
function New-ProofSecret{$bytes=[byte[]]::new(32);$rng=[Security.Cryptography.RandomNumberGenerator]::Create();try{$rng.GetBytes($bytes)}finally{$rng.Dispose()};[Convert]::ToBase64String($bytes)}
cargo build --manifest-path (Join-Path $c.RepoRoot 'tools\docx-tool\Cargo.toml');if($LASTEXITCODE-ne0){throw 'DOCX build failed'};cargo build --manifest-path (Join-Path $c.RepoRoot 'tools\broker-host\Cargo.toml');if($LASTEXITCODE-ne0){throw 'broker host build failed'}
$hostExe=(Resolve-Path $c.BrokerHostExecutable).Path;$docxExe=(Resolve-Path $c.DocxToolExecutable).Path;$bridge=(Resolve-Path (Join-Path $c.RepoRoot 'scripts\runtime\srt-docx-bridge.mjs')).Path;$driver=(Resolve-Path (Join-Path $c.RepoRoot 'scripts\proofs\opencode\permission-driver.mjs')).Path;$source=(Resolve-Path (Join-Path $c.RepoRoot 'tests\fixtures\spike-001-original.docx')).Path;$sourceHash=(Get-FileHash -Algorithm SHA256 $source).Hash.ToLowerInvariant();$node=(Get-Command node.exe).Source;$results=@()
foreach($index in 0..2){$action=@('once','reject','abort')[$index];$root=Join-Path ([IO.Path]::GetFullPath($env:TEMP)) ('ollama-cowork-opencode-docx-'+[guid]::NewGuid().ToString('N'));$private=Join-Path $root 'private';$published=Join-Path $root 'published';New-Item -ItemType Directory -Path $private,$published -Force|Out-Null;$brokerPort=$BrokerPortBase+$index;$opencodePort=$OpencodePortBase+$index;$auth=New-ProofSecret;$controlAuth=New-ProofSecret;$jobToken=New-ProofSecret;$jobId="docx-$action";$configPath=Join-Path $root 'broker-config.json';$config=@{schema_version=1;port=$brokerPort;auth_token=$auth;control_auth_token=$controlAuth;job_id=$jobId;job_token=$jobToken;source=$source;source_sha256=$sourceHash;private_output_directory=$private;publish_directory=$published;node=$node;srt_bridge=$bridge;docx_tool=$docxExe;srt_win=$c.SrtWinPath;read_roots=@($c.RepoRoot)};[IO.File]::WriteAllText($configPath,($config|ConvertTo-Json -Depth 8));$hostProc=$null;$runtime=$null
 try{$hostProc=Start-Process -FilePath $hostExe -ArgumentList @($configPath) -WindowStyle Hidden -RedirectStandardOutput (Join-Path $root 'broker-stdout.log') -RedirectStandardError (Join-Path $root 'broker-stderr.log') -PassThru;$headers=@{Authorization="Bearer $auth"};for($i=0;$i-lt40;$i++){try{$health=Invoke-RestMethod -Uri "http://127.0.0.1:$brokerPort/health" -Headers $headers -TimeoutSec 2;if($health.healthy){break}}catch{};Start-Sleep -Milliseconds 250};if(-not$health.healthy){throw 'broker health failed'}
  $runtime=Start-OpencodeProofRuntime -Name "opencode-docx-$action" -Port $opencodePort -Permission @{'*'='deny';docx_inspect='allow';docx_rewrite_section='ask'} -ToolFiles @((Join-Path $c.RepoRoot 'scripts\proofs\opencode\tools\bash.ts'),(Join-Path $c.RepoRoot 'scripts\proofs\opencode\tools\docx_inspect.ts'),(Join-Path $c.RepoRoot 'scripts\proofs\opencode\tools\docx_rewrite_section.ts')) -Environment @{SPIKE_BROKER_URL="http://127.0.0.1:$brokerPort";SPIKE_BROKER_AUTH=$auth};$session=Invoke-OpencodeJson $runtime '/session' Post @{title="Spike DOCX $action"};$requestPath=Join-Path $root 'permission-request.json';$resultPath=Join-Path $root 'permission-result.json';$prompt='Call docx_rewrite_section exactly once with heading "Executive Summary" and replacement_paragraphs ["Approved headless rewrite through opencode.","The trusted broker must create a revised copy."]. Do not use any other tool. After success answer exactly COMPLETE.';$request=@{schema_version=1;base_url=$runtime.BaseUrl;authorization=$runtime.Authorization;session_id=$session.id;action=$action;token='unused';tool_name='docx_rewrite_section';argument_name='unused';execution_marker='unused';output_contains='artifact';prompt=$prompt;result_path=$resultPath;timeout_ms=120000;broker_control_url="http://127.0.0.1:$brokerPort";broker_control_authorization="Bearer $controlAuth";broker_job_id=$jobId};[IO.File]::WriteAllText($requestPath,($request|ConvertTo-Json -Depth 8));$old=$ErrorActionPreference;try{$ErrorActionPreference='Continue';&$node $driver $requestPath|Out-Host;$exit=$LASTEXITCODE}finally{$ErrorActionPreference=$old};$result=Get-Content -Raw $resultPath|ConvertFrom-Json;$artifacts=@(Get-ChildItem $published -Filter *.docx -File);$artifactPass=if($action-eq'once'){$artifacts.Count-eq1}else{$artifacts.Count-eq0};$results+=[pscustomobject]@{action=$action;driver_passed=$result.passed;artifact_count=$artifacts.Count;artifact_passed=$artifactPass;permission_requested=$result.permission_requested;broker_decision=$result.broker_decision.accepted;executed=$result.executed};if($exit-ne0-or-not$result.passed-or-not$artifactPass-or-not$result.broker_decision.accepted){throw "opencode DOCX scenario failed: $action"}
 }finally{if($runtime){Stop-OpencodeProofRuntime $runtime $true};if($hostProc-and-not$hostProc.HasExited){Stop-Process $hostProc.Id -Force -ErrorAction SilentlyContinue};Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}}
$report=[pscustomobject]@{generated_at=(Get-Date).ToUniversalTime().ToString('o');opencode_version=$c.OpencodeVersion;srt_version=$c.SrtVersion;model=$c.ModelId;scenarios=$results;passed=@($results|Where-Object{-not$_.driver_passed-or-not$_.artifact_passed}).Count-eq0};[IO.File]::WriteAllText((Join-Path $c.EvidenceRoot 'spike-001-opencode-docx-proof-result.json'),($report|ConvertTo-Json -Depth 10));$results|Format-Table -AutoSize
